--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,50 @@ export interface Record {
   warns: readonly string[];
 }

+function extractKeywords(text: string): Set<string> {
+  return new Set(
+    text
+      .toLowerCase()
+      .split(/\W+/)
+      .filter(w => w.length > 2)
+  );
+}
+
+function jaccardSimilarity(a: string, b: string): number {
+  const keywordsA = extractKeywords(a);
+  const keywordsB = extractKeywords(b);
+
+  if (keywordsA.size === 0 && keywordsB.size === 0) return 1;
+  if (keywordsA.size === 0 || keywordsB.size === 0) return 0;
+
+  const common = [...keywordsA].filter(k => keywordsB.has(k)).length;
+  const union = new Set([...keywordsA, ...keywordsB]).size;
+
+  return common / union;
+}
+
+function deduplicate(entries: readonly string[]): string[] {
+  const result: string[] = [];
+
+  for (const entry of entries) {
+    const isSimilar = result.some(existing => jaccardSimilarity(entry, existing) > 0.35);
+    if (!isSimilar) {
+      result.push(entry);
+    }
+  }
+
+  return result;
+}
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
-  for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
-  }
+  const ruledOut = deduplicate(records.flatMap(r => r.ruledOut));
+  const limits = deduplicate(records.flatMap(r => r.limits));
+  const warns = deduplicate(records.flatMap(r => r.warns));
+
+  for (const entry of ruledOut) lines.push(`- ruled out: ${entry}`);
+  for (const entry of limits) lines.push(`- limit: ${entry}`);
+  for (const entry of warns) lines.push(`- warn: ${entry}`);
+
   return lines.join("\n");
 };
